INSERT INTO "_mocha_migrations" ("number","up_sql","down_sql","applied_at") VALUES(1,replace('CREATE TABLE click_events (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  button_type TEXT NOT NULL,\n  page_url TEXT,\n  user_agent TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_click_events_button_type ON click_events(button_type);\nCREATE INDEX idx_click_events_created_at ON click_events(created_at);\n\nCREATE TABLE email_reports (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  report_date DATE NOT NULL,\n  sent_at DATETIME,\n  is_sent BOOLEAN DEFAULT 0,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_email_reports_report_date ON email_reports(report_date);','\n',char(10)),replace('DROP INDEX idx_email_reports_report_date;\nDROP TABLE email_reports;\nDROP INDEX idx_click_events_created_at;\nDROP INDEX idx_click_events_button_type;\nDROP TABLE click_events;','\n',char(10)),'2026-03-30 02:49:10');
