PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE _mocha_migrations (
number     INTEGER UNIQUE,
up_sql     TEXT NOT NULL,
down_sql   TEXT NOT NULL,
applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE click_events (
id INTEGER PRIMARY KEY AUTOINCREMENT,
button_type TEXT NOT NULL,
page_url TEXT,
user_agent TEXT,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE email_reports (
id INTEGER PRIMARY KEY AUTOINCREMENT,
report_date DATE NOT NULL,
sent_at DATETIME,
is_sent BOOLEAN DEFAULT 0,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_click_events_button_type ON click_events(button_type);
CREATE INDEX idx_click_events_created_at ON click_events(created_at);
CREATE INDEX idx_email_reports_report_date ON email_reports(report_date);
